}



.page-header.type22 .main-panel-top .separator {
    height: 32px;
    display: none;
}

.header-bottom.main-menu-wrap>.header-row.container {
    position: relative;
}

.header-bottom.main-menu-wrap>.header-row.container:before {
    content: '';
    position: absolute;
    top: 0;
    bottom: 0;
    background: var(--header-menu-bgcolor);
    z-index: -1;
    left: 10px;
    right: 10px;
    border-radius: 10px;
}

.main-toggle-menu .menu-title {
    font-family: Poppins;
    font-weight: 700;
    font-size: 16px;
    line-height: 150%;
    letter-spacing: 0.15px;
    border: none;
    background: var(--header-menu-bgcolor) !important;
    border-radius: 10px;
    padding-right: 60px;
    padding-left: 10px;
}



.main-toggle-menu .menu-title .toggle {
    font-weight: 600;
}

.main-toggle-menu:not(.without-color-theme) .menu-title.closed:not(:hover) {
    color:  #013569 !important;
}

.main-toggle-menu .menu-title:hover,
.main-toggle-menu:not(.without-color-theme) .menu-title:hover,
.main-toggle-menu:not(.without-color-theme) .menu-title:not(.closed) {
    color: var(--header-menu-hover-color) !important;
    background: var(--header-menu-hover-bgcolor) !important;
}

.main-toggle-menu .menu-title:after {
    display: none;
}

